-- ============================================================================
-- HOSPITAL PILOTO · AGENDA Y CHAT DE PILOTO (v4.2.72, B7a) — datos de DEMOSTRACIÓN (100 % FICTICIOS)
-- ============================================================================
-- Qué es: lo que el frontend sembraba a mano con scripts sueltos (que se perdían al reiniciar) para ver la agenda del personal de apoyo y la bandeja
-- de mensajes con algo dentro. Aquí queda versionado y repetible:
--   · una agenda (recurso) por cada doctor del piloto (8: 7 del hospital + la Dra. Céspedes del consultorio), con CUPOS LIBRES de los días
--     miércoles 2026-11-04 a viernes 2026-11-06 (dos por espacio y día; una persona de apoyo ve la agenda con huecos reales) y 7 reservas confirmadas;
--   · 4 pacientes ficticios CON CUENTA (sin credenciales: no pueden iniciar sesión) cuya persona se vincula a su cuenta por
--     `profiles.person_account_links` (vínculo ACTIVO, titular, verificado) y tiene su `patient_profiles`: así la API resuelve el `patientProfileId`
--     de una conversación igual que en producción (`SupportInboxRepository.patientContext`: usuario → vínculo activo → perfil de paciente);
--   · perfiles públicos de chat de los 8 doctores y de los 4 pacientes, y 4 conversaciones directas (una sin atender de hace 1 día, una con síntomas
--     de hace 4 h para la bandeja de «urgente», etc.), cada una con su mensaje del paciente.
-- TODOS los ids son uuid5 REALES (versión 5, variante RFC 4122: pasan IsUUID de los validadores de la API; los ids sacados de md5 se rechazaban):
-- uuid5(3f2b6c14-…, 'demo:piloto:<tipo>:<clave>'), literales en el script. Los de las 5 agendas que ya trae 07 se reutilizan (mismo id y nombre),
-- así 09 no depende de 07 ni duplica nada en ningún orden.
--
-- Cuándo correrlo: DESPUÉS de `04-hospital-piloto.sql` (y, si se usa, de 07; el orden entre 07 y 09 da igual) y de los parches v4269 y v4272.
-- Idempotente: ids deterministas + ON CONFLICT DO NOTHING; volver a correrlo no duplica ni reescribe nada. Las fechas de los CUPOS y las reservas son
-- ABSOLUTAS (la misma referencia que 07: «hoy» = martes 2026-11-03); las del CHAT son relativas al momento de la carga («hace 35 minutos»).
-- Verifica: `10-verifica-agenda-chat-piloto.sql`.
--
-- GUARDA B4 (como 04 y 07): crea cuentas (sin contraseña, pero de personas) en una organización de demostración; exige bandera explícita y, sin
-- ella, FALLA antes de escribir nada (una sola transacción):
--     psql -v ON_ERROR_STOP=1 -v demo_accounts=1 -d <base> -f salud-db/demo/09-agenda-chat-piloto.sql
-- (equivalente: `\set demo_accounts 1` o PGOPTIONS="-c mantra.demo_accounts=1"). Valores aceptados: 1, true, on, yes. NO cargar en producción.
-- ============================================================================

BEGIN;

-- GUARDA B4: sin la bandera explícita no se crea nada.
\if :{?demo_accounts}
  SELECT set_config('mantra.demo_accounts', :'demo_accounts', false);
\endif
DO $guard$
BEGIN
  IF lower(COALESCE(current_setting('mantra.demo_accounts', true), '')) NOT IN ('1', 'true', 'on', 'yes') THEN
    RAISE EXCEPTION 'agenda y chat del hospital piloto (demo): este script crea cuentas de pacientes ficticios y no corre sin consentimiento explícito. Vuelve a correrlo con -v demo_accounts=1 (o \set demo_accounts 1) SOLO en una base de demostración o pruebas, nunca en producción.'
      USING ERRCODE = 'insufficient_privilege',
            HINT = 'psql -v ON_ERROR_STOP=1 -v demo_accounts=1 -d <base> -f salud-db/demo/09-agenda-chat-piloto.sql';
  END IF;
  -- el escenario cuelga del hospital y del consultorio de 04: sin ellos no hay a qué agregar agenda
  IF (SELECT count(*) FROM directory.tenants WHERE id IN ('830e47e1-8e82-50ff-99c0-bfed0a7971a4', 'a52f851c-e5c2-5a32-b99e-a4993ff5a287')) <> 2 THEN
    RAISE EXCEPTION 'agenda y chat del hospital piloto (demo): faltan el Hospital Piloto o el consultorio de 04-hospital-piloto.sql; córralo primero'
      USING ERRCODE = 'undefined_object';
  END IF;
  RAISE WARNING 'agenda y chat del hospital piloto (demo): se crearán pacientes y cuentas ficticias en la base %', current_database();
END
$guard$;

-- 0 · Conceptos que esta demo usa. Mismos ids que deriva la API (uuid5 sobre su namespace): si la API ya arrancó, o si 04/07 ya los cargaron, es un no-op.
ON CONFLICT DO NOTHING;

-- 1 · Una agenda (recurso programable) por doctor. Las 5 primeras son las mismas filas de 07 (mismo id y nombre).
ON CONFLICT DO NOTHING;

-- La API nombra la tabla de perfiles como `health_practitioner_profiles` (o `practitioner_profiles`: PRACTITIONER_PROFILE_TABLES); con el nombre
-- calificado `profiles.health_practitioner_profiles` que traían las versiones anteriores la política de agenda no encuentra al doctor de la cita y todo
-- da DOCTOR_NOT_ACCEPTED. Este UPDATE normaliza también una base ya cargada con el nombre antiguo (no toca ninguna otra fila).
UPDATE scheduling.schedulable_resources SET resource_ref_type = 'health_practitioner_profiles', updated_at = now()
 WHERE resource_ref_type = 'profiles.health_practitioner_profiles' AND name LIKE 'Agenda % (DEMO)';

-- 2 · Cupos de 30 minutos: miércoles 4 a viernes 6 de noviembre de 2026 (hora de La Paz), dos por espacio y día (a distinto horario por espacio de un mismo
--     doctor: nadie ofrece dos lugares a la misma hora). Los 7 reservados nacen ocupados (capacidad restante 0, estado «reservado»).
ON CONFLICT DO NOTHING;

-- 3 · 4 pacientes ficticios con cuenta (sin credenciales de acceso): cuenta, persona, perfil de paciente y vínculo cuenta↔persona (titular, verificado, ACTIVO).
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- El `patientProfileId` de una conversación sale de aquí: usuario → vínculo ACTIVO sin fecha de fin → `patient_profiles.profile_id` (= la persona).
ON CONFLICT DO NOTHING;

-- 4 · 7 reservas confirmadas (todas con booked_via_grant_id NULL; los motivos son frases ficticias, sin datos de nadie). La última cita de cada paciente con su
--     doctor es el «motivo» que la bandeja muestra junto a la conversación.
ON CONFLICT DO NOTHING;

-- 5 · Chat. Perfiles públicos de los 8 doctores (visibles en el directorio) y de los 4 pacientes (privados).
ON CONFLICT DO NOTHING;

-- Conversaciones directas, ancladas al hospital (hay una sin atender de hace 1 día y una de hace 265 minutos con síntomas: material para la bandeja).
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

COMMIT;

\echo == agenda y chat del hospital piloto (demo) cargados ==
SELECT (SELECT count(*) FROM scheduling.schedulable_resources WHERE name LIKE 'Agenda % (DEMO)') AS agendas,
       (SELECT count(*) FROM scheduling.bookable_slots s JOIN scheduling.schedulable_resources r ON r.id = s.resource_id WHERE r.name LIKE 'Agenda % (DEMO)' AND s.status_concept_id = '10960d55-a26d-51ab-98ef-48b1d64b306b') AS cupos_libres,
       (SELECT count(*) FROM profiles.patient_profiles WHERE patient_code LIKE 'DEMO-PIL-P%') AS pacientes_con_cuenta,
       (SELECT count(*) FROM community.conversations WHERE id IN ('fab39907-9b08-5b6b-8709-ffebb16ff56a', '02b4bd9b-a2e0-5212-800d-903d5b8671ac', 'ee02705e-e298-5e98-9667-021c3ac508e8', 'd69773db-4739-5810-8dbf-ea0e6c7ed8b8')) AS conversaciones;
