INSERT INTO community.direct_messages (id, conversation_id, sender_profile_id, content_type_concept_id, body_text, status_concept_id, sent_at, created_at, updated_at, row_version, disclosure_shown) VALUES
  ('d51dcf43-2b09-5390-9cb4-41fe899d3516', 'fab39907-9b08-5b6b-8709-ffebb16ff56a', '67b40e6e-22d9-504d-87a5-8996e21f71c2', '4bfcb439-b759-52c4-bfa1-3425f78d96d2', 'Buenas tardes. ¿Puedo cambiar mi cita del jueves a la tarde? Me salió un compromiso de trabajo.', 'f375d6f4-ccd8-5bab-a5e9-892b20568262', now() - interval '35 minutes', now() - interval '35 minutes', now() - interval '35 minutes', 1, false),
  ('7a4c83c0-8e86-536a-a9aa-b0b89a8b6119', '02b4bd9b-a2e0-5212-800d-903d5b8671ac', 'edc59ea6-c1b8-5639-8a50-aafe1f38bb24', '4bfcb439-b759-52c4-bfa1-3425f78d96d2', 'Doctor, desde anoche tengo dolor fuerte en el pecho y me falta el aire. ¿Puedo tomar doble dosis del atenolol?', 'f375d6f4-ccd8-5bab-a5e9-892b20568262', now() - interval '265 minutes', now() - interval '265 minutes', now() - interval '265 minutes', 1, false),
  ('606ed168-cd36-5c0e-9fd3-45bd0134c533', 'ee02705e-e298-5e98-9667-021c3ac508e8', 'a8d1ac9a-7ec1-5e77-85e8-35d6946e83ef', '4bfcb439-b759-52c4-bfa1-3425f78d96d2', 'Doctora, buenos días. ¿Debo ir en ayunas a la ecografía del jueves?', 'f375d6f4-ccd8-5bab-a5e9-892b20568262', now() - interval '2 hours', now() - interval '2 hours', now() - interval '2 hours', 1, false),
  ('93d446bd-7604-54eb-a90d-9b634c3fdad6', 'd69773db-4739-5810-8dbf-ea0e6c7ed8b8', '8fc28324-e69a-55a4-bda8-2c98c45ff8a9', '4bfcb439-b759-52c4-bfa1-3425f78d96d2', 'Hola doctora. Necesito el comprobante de mi última atención para mi seguro, ¿me lo pueden enviar?', 'f375d6f4-ccd8-5bab-a5e9-892b20568262', now() - interval '1 day', now() - interval '1 day', now() - interval '1 day', 1, false)
